// Single Cloudflare Worker for sanjal.com. Generated by site/build-worker.py
// from site/public/index.html and site/functions/api/waitlist.js; edit those.
const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Sanjal \u00b7 Your agent, working for you</title>\n<meta name=\"description\" content=\"Sanjal. Your agent, working for you. Coming soon.\">\n<style>\n  :root { --bg:#fbfaf7; --text:#16181d; --muted:#5d6470; --accent:#0f5f4b; --line:#d9d6cf; --field:#ffffff; }\n  @media (prefers-color-scheme: dark) {\n    :root { --bg:#0e1113; --text:#f1efe9; --muted:#a3a9b3; --accent:#5fd0ae; --line:#2a2f35; --field:#161a1d; }\n  }\n  * { box-sizing: border-box; }\n  html, body { height: 100%; }\n  body { margin:0; background:var(--bg); color:var(--text);\n    font-family: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; line-height:1.5;\n    display:flex; flex-direction:column; }\n  main { flex:1; display:flex; flex-direction:column; justify-content:center;\n    max-width:620px; width:100%; margin:0 auto; padding:48px 20px; }\n  .brand { font-weight:700; letter-spacing:.02em; font-size:1.1rem; color:var(--accent); }\n  h1 { font-size:clamp(2.2rem, 8vw, 3.4rem); line-height:1.05; letter-spacing:-.02em; margin:20px 0 32px; }\n  p.lead { font-size:1.15rem; color:var(--muted); margin:0 0 28px; max-width:34em; }\n  .soon { font-size:.85rem; font-weight:600; text-transform:uppercase; letter-spacing:.12em; color:var(--accent); margin-bottom:12px; }\n  form { display:flex; gap:8px; flex-wrap:wrap; }\n  input { flex:1 1 220px; min-width:0; padding:14px 16px; font:inherit; color:var(--text);\n    background:var(--field); border:1px solid var(--line); border-radius:10px; }\n  button { padding:14px 20px; font:inherit; font-weight:600; border:0; border-radius:10px;\n    background:var(--accent); color:var(--bg); cursor:pointer; }\n  input:focus-visible, button:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n  #note { min-height:1.5em; margin:12px 0 0; color:var(--muted); }\n  footer { text-align:center; color:var(--muted); font-size:.85rem; padding:20px; }\n</style>\n</head>\n<body>\n<main>\n  <div class=\"brand\">Sanjal</div>\n  <h1>Your agent, working for you.</h1>\n  <div class=\"soon\">Coming soon</div>\n  <form id=\"waitlist\" method=\"post\" action=\"/api/waitlist\">\n    <input type=\"email\" name=\"email\" placeholder=\"you@example.com\" aria-label=\"Email address\" autocomplete=\"email\" required>\n    <button type=\"submit\">Get early access</button>\n  </form>\n  <p id=\"note\" role=\"status\" aria-live=\"polite\"></p>\n</main>\n<footer>\u00a9 Sanjal \u00b7 sanjal.com</footer>\n<script>\n  const form = document.getElementById('waitlist');\n  const note = document.getElementById('note');\n  form.addEventListener('submit', async (event) => {\n    event.preventDefault();\n    const button = form.querySelector('button');\n    button.disabled = true;\n    note.textContent = '';\n    try {\n      const res = await fetch(form.action, {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({ email: form.email.value }),\n      });\n      const data = await res.json();\n      if (data.ok) {\n        form.reset();\n        note.textContent = \"You're on the list. We'll email you when Sanjal opens.\";\n      } else if (data.error === 'invalid_email') {\n        note.textContent = 'Please check the email address and try again.';\n      } else {\n        note.textContent = 'Something went wrong. Please try again in a moment.';\n      }\n    } catch {\n      note.textContent = 'Something went wrong. Please try again in a moment.';\n    }\n    button.disabled = false;\n  });\n</script>\n</body>\n</html>\n";

// Saves a waitlist email to the WAITLIST KV namespace.
// Key: the lowercased email. Value: when it was first added.
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function json(body, status) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' },
  });
}

async function saveEmail(request, env) {
  let email = '';
  try {
    const type = request.headers.get('content-type') || '';
    if (type.includes('application/json')) {
      email = (await request.json()).email;
    } else {
      email = (await request.formData()).get('email');
    }
  } catch {
    return json({ ok: false, error: 'bad_request' }, 400);
  }

  email = String(email || '').trim().toLowerCase();
  if (email.length > 254 || !EMAIL.test(email)) {
    return json({ ok: false, error: 'invalid_email' }, 400);
  }
  if (!env.WAITLIST) {
    return json({ ok: false, error: 'not_configured' }, 503);
  }

  const existing = await env.WAITLIST.get(email);
  if (!existing) {
    await env.WAITLIST.put(email, new Date().toISOString());
  }
  return json({ ok: true }, 200);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.hostname === 'www.sanjal.com') {
      url.hostname = 'sanjal.com';
      return Response.redirect(url.toString(), 301);
    }
    if (url.pathname === '/api/waitlist') {
      if (request.method !== 'POST') {
        return json({ ok: false, error: 'method_not_allowed' }, 405);
      }
      return saveEmail(request, env);
    }
    if (url.pathname === '/' || url.pathname === '/index.html') {
      return new Response(PAGE, {
        headers: {
          'content-type': 'text/html; charset=utf-8',
          'cache-control': 'public, max-age=300',
          'x-content-type-options': 'nosniff',
        },
      });
    }
    return new Response('Not found', { status: 404 });
  },
};
